\set ON_ERROR_STOP on
do $$begin if current_database() !~ '^training_' then raise exception 'Use a disposable local database named training_*'; end if; end$$;
\set ON_ERROR_STOP on
create or replace function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',label;end if;raise notice 'PASS: %',label;end$$;
create or replace function public.test_error(statement text,expected text) returns void language plpgsql as $$declare caught boolean=false;begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then caught=true;else raise;end if;end;if not caught then raise exception 'EXPECTED REJECTION: %',expected;end if;raise notice 'PASS: rejected %',expected;end$$;
grant execute on function public.test_assert(boolean,text),public.test_error(text,text) to authenticated,anon;
set role anon;
select public.test_error('select * from public.training_modules','permission denied');
select public.test_assert((public.training_access()->>'allowed')::boolean=false,'unsigned caller cannot enter training');
select public.test_error($q$select public.training_record('22222222-2222-4222-8222-222222222222','foundation',1,'{}',null)$q$,'Sign in required');
reset role;
set role authenticated;
set request.jwt.claim.sub='55555555-5555-4555-8555-555555555555';
select public.test_assert((select count(*)=0 from public.training_modules),'unassigned account cannot read curriculum');
select public.test_assert((public.training_access()->>'allowed')::boolean=false,'unassigned account cannot enter training');
select public.test_error($q$select public.training_save_module('foundation',1,'{}',null)$q$,'Editor access required');
select public.test_error($q$select public.training_enrol(null,'55555555-5555-4555-8555-555555555555','Outsider','foundation',null,null)$q$,'Pastor access required');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.test_assert((select count(*)=13 from public.training_modules where status='published'),'all 13 complete modules publish');
select set_config('test.learner',public.training_enrol(null,'22222222-2222-4222-8222-222222222222','Fictional learner','foundation','33333333-3333-4333-8333-333333333333',null)::text,false);
select public.training_enrol(null,'22222222-2222-4222-8222-222222222222','Fictional learner','worship','33333333-3333-4333-8333-333333333333',null);
select public.training_enrol(null,'44444444-4444-4444-8444-444444444444','Other fictional learner','foundation',null,null);
select public.training_assign_editor('33333333-3333-4333-8333-333333333333','worship',true);
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.test_assert((select count(*)=1 from public.training_learners),'learner sees only own identity');
select public.test_assert((select count(*)=2 from public.training_enrolments),'learner sees own enrolments');
select public.test_assert((select count(*)=13 from public.training_modules),'learner may explore all published departments');
select public.test_error('update public.training_progress set approved_at=now()','permission denied');
select public.test_error($q$select public.training_review(current_setting('test.learner')::uuid,'foundation',1,true,true,'Pretend evidence')$q$,'Assigned reviewer access required');
select public.training_record(current_setting('test.learner')::uuid,'foundation',1,array['invented'],null);
select public.training_record(current_setting('test.learner')::uuid,'foundation',1,'{}',null);
select public.test_assert((select cardinality(read_lesson_ids)=0 from public.training_progress where module_id='foundation'),'invented lesson IDs ignored; empty updates safe');
select public.training_record(current_setting('test.learner')::uuid,'foundation',1,(select array_agg(l->>'id') from public.training_modules m,jsonb_array_elements(m.content->'lessons') l where m.id='foundation' and m.status='published'),'{"f1":1,"f2":2,"f3":1}');
select public.test_assert((select not quiz_passed and quiz_correct=2 from public.training_progress where module_id='foundation'),'wrong answer does not pass');
select public.training_record(current_setting('test.learner')::uuid,'worship',1,(select array_agg(l->>'id') from public.training_modules m,jsonb_array_elements(m.content->'lessons') l where m.id='worship' and m.status='published'),'{"worship-q1":1,"worship-q2":1,"worship-q3":2}');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.test_assert((select count(*)=1 from public.training_learners),'reviewer sees assigned learner only');
select public.test_error($q$select public.training_review(current_setting('test.learner')::uuid,'worship',1,true,true,'Observed supervised practice')$q$,'Foundation School completion');
select public.test_error($q$select public.training_review(current_setting('test.learner')::uuid,'foundation',1,true,true,'Observed supervised practice')$q$,'Complete reading and knowledge check first');
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.training_record(current_setting('test.learner')::uuid,'foundation',1,'{}','{"f1":1,"f2":2,"f3":0}');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.training_review(current_setting('test.learner')::uuid,'foundation',1,true,true,'Four Sundays and practical testimony observed');
select public.training_review(current_setting('test.learner')::uuid,'worship',1,true,true,'Rehearsal and service practice observed');
select public.test_assert((select approved_at is not null from public.training_progress where module_id='worship'),'department assessment after Foundation approval');
select public.training_save_module('worship',1,(select content||'{"summary":"Revised fictional test summary"}' from public.training_modules where id='worship' and revision=1),(select updated_at from public.training_modules where id='worship' and revision=1));
select public.test_assert((select count(*)=1 from public.training_modules where id='worship' and status='draft'),'published edit creates a new draft');
select public.training_publish('worship',2,'submit');
select public.test_error($q$select public.training_publish('worship',2,'publish')$q$,'pastoral approval');
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.test_assert((select max(revision)=1 from public.training_modules where id='worship'),'unapproved revision invisible to learner');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.training_publish('worship',2,'publish');
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.test_assert((select max(revision)=2 from public.training_modules where id='worship'),'published revision becomes visible');
select public.test_assert((select count(*)=0 from public.training_progress where module_id='worship' and revision=2),'new revision does not inherit previous assessment');
select public.test_error($q$select public.training_record(current_setting('test.learner')::uuid,'worship',1,'{}',null)$q$,'query returned no rows');
select public.test_error($q$select public.training_equivalence(current_setting('test.learner')::uuid,'Invented prior-learning claim',true)$q$,'Pastor access required');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.training_enrol(null,'11111111-1111-4111-8111-111111111111','Fictional pastor','foundation',null,null);
select public.test_error($q$select public.training_equivalence((select id from public.training_learners where user_id=auth.uid()),'Cannot approve my own prior learning',true)$q$,'second pastor');
select public.test_assert((select count(*)>0 from public.training_audit where action='assessment'),'assessment audit trail retained');
reset role;
select public.test_assert(not training_private.validate_content('{"lessons":null}'),'malformed content cannot publish');
select 'Training security and lifecycle assertions passed' as result;
\set ON_ERROR_STOP on
insert into public.congregation_people(id,full_name) values('66666666-6666-4666-8666-666666666666','Fictional in-person student');
insert into public.foundation_classes(id,teacher_id,title) values('77777777-7777-4777-8777-777777777777','33333333-3333-4333-8333-333333333333','Fictional cohort');
insert into public.foundation_students values('77777777-7777-4777-8777-777777777777','66666666-6666-4666-8666-666666666666');
set role authenticated;
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select set_config('test.inperson',public.training_enrol('66666666-6666-4666-8666-666666666666',null,'Fictional in-person student','foundation','33333333-3333-4333-8333-333333333333','77777777-7777-4777-8777-777777777777')::text,false);
select public.test_error($q$select public.training_save_module('worship',2,(select content from public.training_modules where id='worship' and revision=2),'2000-01-01')$q$,'revision changed');
select public.training_save_module('invalid-example',0,(select jsonb_set(content||'{"id":"invalid-example"}','{standards}','[42]'::jsonb) from public.training_modules where id='foundation' and revision=1),null);
select public.training_publish('invalid-example',1,'submit');
select public.test_error($q$select public.training_publish('invalid-example',1,'publish')$q$,'Complete all teaching');
