select public.test_assert((select count(*)=1 from public.training_equivalences),'equivalence stored with evidence');
select public.training_equivalence((select id from public.training_learners where user_id='44444444-4444-4444-8444-444444444444'),'Fictional revocation for the QA test',false);
select public.test_assert((select count(*)=0 from public.training_equivalences),'equivalence revocation retained in audit');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.training_record(current_setting('test.inperson')::uuid,'foundation',1,(select array_agg(l->>'id') from public.training_modules m,jsonb_array_elements(m.content->'lessons') l where m.id='foundation' and revision=1),'{"f1":1,"f2":2,"f3":0}');
select public.training_review(current_setting('test.inperson')::uuid,'foundation',1,true,true,'Observed four sessions and an in-person testimony practice');
select public.test_assert((select approved_at is not null from public.training_progress where learner_id=current_setting('test.inperson')::uuid),'assigned accountless student can be taught and assessed');
select public.test_error($q$select public.training_record((select id from public.training_learners where user_id='22222222-2222-4222-8222-222222222222'),'foundation',1,'{}',null)$q$,'own learner record');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.test_assert((select count(*)>0 from public.training_audit where learner_id=current_setting('test.inperson')::uuid and actor='33333333-3333-4333-8333-333333333333' and detail->>'assisted'='true'),'assisted recording preserves actual actor');
select public.test_error($q$select public.training_review((select id from public.training_learners where user_id=auth.uid()),'foundation',1,true,true,'Attempt to approve my own work')$q$,'second leader');
reset role;
select public.test_assert(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'training_%' and p.prosecdef),'exposed training endpoints do not bypass RLS');
select 'Additional workflow and validation assertions passed' as result;
